    public Object handleMethodCall(Object stubbedObject, String stubbedMethodName, Type returnType,
            List<Type> listOfParamTypes, List<String> listOfParamNames, List<Object> listOfArgs) {
        seen.add(stubbedMethodName + '{self=' + String.valueOf(stubbedObject)
            + ' ; ret=' + String.valueOf(returnType)
            + ' ; retName=' + (returnType == null ? 'null' : returnType.getName())
            + ' ; types=' + String.valueOf(listOfParamTypes)
            + ' ; typesConcat=' + listOfParamTypes
            + ' ; names=' + String.valueOf(listOfParamNames) + '}');
        if (returnType == String.class) {
            return 'stubbed-' + stubbedMethodName;
        }
        return null;
    }
}

